#m_r_imgbox_0 img@data-src
@js:
var lines = result.split("\n");
var newLines = [];
for (var i = 0; i < lines.length; i++) {
  if (lines[i]) {
    newLines.push('<img src="' + lines[i] + '">');
  }
}
newLines.join("\n")

ruleToc.chapterList:
@js:
const doc = org.jsoup.Jsoup.parse(result);
const links = doc.select("span.vol-item-info a");
const chapters = [];
for (var i = 0; i < links.size(); i++) {
    var a = links.get(i);
    chapters.push({
        title: String(a.text()),
        url: String(a.attr("href"))
    });
}
chapters.reverse();
chapters;
